import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let n = {n} and r = {r} with 3 ≤ r ≤ n. All indices below are read cyclically modulo {n}. Determine the largest real constant C (depending only on {n} and {r}) such that for every choice of {n} positive integers x_1, x_2, ..., x_{n} we have\n\nSum over i=1..{n} of (x_i + x_{i+1} + ... + x_{i+{r_minus_1}})^{r} ≥ C * gcd(x_1, x_2, ..., x_{n}) * Sum over i=1..{n} of lcm(x_i, x_{i+1}, ..., x_{i+{r_minus_1}}).\n\nFind the exact value of C in terms of r and n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose r in a moderately challenging range
r = rng.randint(3, 6)  # 3,4,5,6
# Choose n at least r and not too large for clarity, but variable enough
extra = rng.randint(3, 10)
n = rng.randint(r, min(20, r + extra))
return {'n': n, 'r': r, 'r_minus_1': r-1}

