    r = int(assign['r'])
    r_minus_1 = int(assign['r_minus_1'])
except Exception:
    # missing or non-integer slots
    return (False, None)
if r_minus_1 != r - 1:
    # inconsistent slots
    return (False, None)
if n < r or r < 3:
    return (False, None)
# The claimed optimal constant
answer = r**r

# Robust randomized verification of the inequality for this C
# Inequality to verify:
# sum_i (sum_{j=0..r-1} x_{i+j})^r >= C * gcd(all) * sum_i lcm(x_i, ..., x_{i+r-1})
# with indices modulo n.

from math import gcd

def lcm(a, b):
    return a // gcd(a, b) * b

def lcm_list(vals):
    from functools import reduce
    return reduce(lcm, vals, 1)

def gcd_list(vals):
    from functools import reduce
    return reduce(gcd, vals)

# Random stress tests to guard against accidental incorrect constants
rng_state = 123456789  # deterministic seed for verifier's internal RNG
def rnd():
    # Simple LCG for deterministic pseudo-randomness in verifier
    nonlocal rng_state
    rng_state = (1103515245 * rng_state + 12345) & 0x7fffffff
    return rng_state

def randint(a, b):
    return a + (rnd() % (b - a + 1))

# perform several trials of random vectors
for _ in range(60):
    xs = [randint(1, 20) for __ in range(n)]
    g_all = gcd_list(xs)
    # compute LHS
    lhs = 0
    for i in range(n):
        s = 0
        for j in range(r):
            s += xs[(i + j) % n]
        lhs += s**r
    # compute RHS part (without C)
    rhs_core = 0
    for i in range(n):
        block = [xs[(i + j) % n] for j in range(r)]
        rhs_core += lcm_list(block)
    rhs = g_all * rhs_core
    # Check inequality: lhs >= answer * rhs
    if lhs < answer * rhs:
        # If this ever happens, the proposed constant is too large
        return (False, None)

# Tightness check with all ones vector to justify optimality: ratio equals r^r
xs = [1]*n
# LHS with ones: each window sum = r, so each contributes r^r
lhs_ones = n * (r**r)
# RHS core with ones: each window lcm is 1, gcd(all)=1
rhs_core_ones = n
rhs_ones = rhs_core_ones
# The maximal admissible C cannot exceed lhs/rhs in this witness
max_by_witness = lhs_ones // rhs_ones if lhs_ones % rhs_ones == 0 else lhs_ones / rhs_ones
# Ensure our answer does not exceed the witness bound
if answer > max_by_witness + 1e-12:
    return (False, None)

return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
